UPDATE document_definition_versions
SET schema_json = '{"code":"CANADA_PERMANENT_RESIDENT","country":"CA","documentType":"RESIDENCE_PERMIT","version":"2015","side":"BACK","mrzFormat":"TD1","reading":"Canada permanent resident card back. The machine-readable zone is three lines, and each line has exactly 30 characters. Copy every character of each line, including every < filler at the end. In a name, the round letter is O and the digit is 0. lastName includes every surname before the double filler, including a surname printed twice. expirationDate is only the expiry date encoded in the second MRZ line.","fields":[{"name":"documentNumber","type":"DOCUMENT_NUMBER","required":true,"hint":"the PD number printed above the machine-readable zone; do not use the front ID No"},{"name":"lastName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"every surname on the third MRZ line before the double filler, including a surname printed twice"},{"name":"firstName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"given names from the third MRZ line, after the double filler"},{"name":"dateOfBirth","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"birth date from the MRZ; write yyyy-MM-dd"},{"name":"expirationDate","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"expiry date encoded in the second MRZ line; write yyyy-MM-dd, and a year 30 is 2030"},{"name":"sex","type":"SEX","required":false,"hint":"sex letter from the MRZ"},{"name":"nationality","type":"NATIONALITY","required":false,"hint":"nationality alpha-3 from the MRZ, such as CMR"},{"name":"mrz","type":"MRZ","required":true,"hint":"three lines of exactly 30 characters each; copy every < filler. A name uses the letter O, not the digit 0"},{"name":"placeOfLanding","type":"STRING","required":false,"hint":"labeled Place of landing"},{"name":"residentSince","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"labeled PR Since; write yyyy-MM-dd"},{"name":"eyeColor","type":"STRING","required":false,"hint":"labeled Eyes"},{"name":"heightCm","type":"STRING","required":false,"hint":"labeled Height, digits only"},{"name":"countryOfBirth","type":"NATIONALITY","required":false,"hint":"labeled COB, alpha-3 such as CMR"}],"rules":[]}'
WHERE id = '018f5a00-0000-7000-8000-0000000000e4';
